export {};
import React, { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import { 
  Package, 
  Truck, 
  Search, 
  CheckCircle, 
  Clock, 
  MapPin, 
  Phone, 
  Mail,
  ChevronRight,
  Star,
  ArrowRight,
  AlertCircle,
  Cloud,
  Navigation,
  Calendar,
  Map,
  Route,
  Settings,
  AlertTriangle,
  Users,
  Brain
} from 'lucide-react';
import * as L from 'leaflet';
import 'leaflet/dist/leaflet.css';

interface OrderStatus {
  id: string;
  status: 'pending' | 'processing' | 'shipped' | 'delivered' | 'cancelled';
  estimatedDelivery: string;
  items: { name: string; quantity: number }[];
  currentLocation: string;
  lastUpdate: string;
  trackingNumber: string;
  customerName: string;
  deliveryAddress: string;
  priority: 'standard' | 'express' | 'premium';
  assignedEmployee?: {
    id: string;
    name: string;
    phone: string;
    currentLocation?: { lat: number; lng: number };
  };
  coordinates: { lat: number; lng: number };
  delayStatus: 'on_time' | 'delayed';
  delayReason?: string;
  weatherImpact: boolean;
  trafficImpact: boolean;
  orderTime: string;
  actualDeliveryTime?: string;
}

interface WeatherData {
  location: string;
  temperature: number;
  condition: string;
  humidity: number;
  windSpeed: number;
  visibility: number;
  icon: string;
}

interface DeliveryPerson {
  id: string;
  name: string;
  phone: string;
  currentLocation: { lat: number; lng: number };
  currentLoad: number;
  maxLoad: number;
  route: string;
  availability: 'available' | 'busy' | 'off_duty';
  efficiency: number;
}

const CustomerPortal: React.FC = () => {
  const [orderId, setOrderId] = useState('');
  const [orderStatus, setOrderStatus] = useState<OrderStatus | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [showRescheduleModal, setShowRescheduleModal] = useState(false);
  const [showAddressModal, setShowAddressModal] = useState(false);
  const [newDeliveryTime, setNewDeliveryTime] = useState('');
  const [newAddress, setNewAddress] = useState({ address: '', coordinates: { lat: 0, lng: 0 } });
  const [actionLoading, setActionLoading] = useState(false);
  const [recommendedDeliveryPeople, setRecommendedDeliveryPeople] = useState<DeliveryPerson[]>([]);
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<L.Map | null>(null);

  // Mock recommended delivery people data
  const mockRecommendedDeliveryPeople: DeliveryPerson[] = [
    {
      id: 'EMP004',
      name: 'Suresh Kumar',
      phone: '+91-98765-11111',
      currentLocation: { lat: 28.6200, lng: 77.2000 },
      currentLoad: 2,
      maxLoad: 5,
      route: 'Delhi - Noida - Ghaziabad',
      availability: 'available',
      efficiency: 92
    },
    {
      id: 'EMP005',
      name: 'Anjali Sharma',
      phone: '+91-98765-22222',
      currentLocation: { lat: 28.6000, lng: 77.1800 },
      currentLoad: 1,
